sp_widget.client_script:
api.controller = function($scope,spUtil,$window,$timeout,nowAttachmentHandler) {

    var c = this;

    c.submitting = false;
    c.uploading = false;
    c.attachments = c.data.attachments || [];

    /*
     * Record picker models
     */
    c.employeeField = {
        displayValue: c.data.employeeDisplay || "",
        value: c.data.employee || "",
        name: "u_employee_name"
    };

    c.countryField = {
        displayValue: c.data.countryDisplay || "",
        value: c.data.country || "",
        name: "u_country"
    };

    c.managerField = {
        displayValue: c.data.managerDisplay || "",
        value: c.data.manager || "",
        name: "u_manager_email"
    };

    c.l2ManagerField = {
        displayValue: c.data.l2ManagerDisplay || "",
        value: c.data.l2Manager || "",
        name: "u_management_l2"
    };

    c.trainingCountryField = {
        displayValue:
            c.data.trainingCountryDisplay || "",
        value:
            c.data.trainingCountry || "",
        name:
            "u_training_country"
    };

    /*
     * Convert server date string to JavaScript Date.
     */
    function convertToDate(value) {

        if (!value) {
            return null;
        }

        if (angular.isDate(value)) {
            return value;
        }

        var dateValue =
            value.toString().substring(0, 10);

        var parts =
            dateValue.split("-");

        if (parts.length !== 3) {
            return null;
        }

        return new Date(
            parseInt(parts[0], 10),
            parseInt(parts[1], 10) - 1,
            parseInt(parts[2], 10)
        );
    }

    c.data.courseStartDate =
        convertToDate(
            c.data.courseStartDate
        );

    c.data.courseEndDate =
        convertToDate(
            c.data.courseEndDate
        );

    /*
     * Store original values for Clear.
     */
    var originalData =
        angular.copy(c.data);

    var originalEmployee =
        angular.copy(c.employeeField);

    var originalCountry =
        angular.copy(c.countryField);

    var originalManager =
        angular.copy(c.managerField);

    var originalL2Manager =
        angular.copy(c.l2ManagerField);

    var originalTrainingCountry =
        angular.copy(c.trainingCountryField);

    /*
     * Attachment upload success.
     */
    function attachmentSuccess(attachments) {

        c.uploading = false;

        if (angular.isArray(attachments)) {
            c.attachments = attachments;
        }

        c.refreshAttachments();

        spUtil.addInfoMessage(
            "Attachment uploaded successfully."
        );

        $scope.$applyAsync();
    }

    /*
     * Attachment upload failure.
     */
    function attachmentError(error) {

        c.uploading = false;

        spUtil.addErrorMessage(
            error && error.message
                ? error.message
                : "Unable to upload the attachment."
        );

        $scope.$applyAsync();
    }

    /*
     * Initialize attachment handler.
     */
    c.attachmentHandler =
        new nowAttachmentHandler(
            attachmentSuccess,
            attachmentError
        );

    c.attachmentHandler.setParams(
        c.data.table,
        c.data.sys_id,
        24 * 1024 * 1024
    );

    /*
     * Open attachment picker.
     */
    c.openAttachmentPicker = function() {

        var input =
            document.getElementById(
                "learningAttachmentInput"
            );

        if (input) {
            input.value = "";
            input.click();
        }
    };

    /*
     * Upload selected files.
     */
    c.uploadAttachments = function(files) {

        if (!files || !files.length) {
            return;
        }

        c.uploading = true;

        angular.forEach(
            files,
            function(file) {
                c.attachmentHandler
                    .onFileSelect(file);
            }
        );

        $scope.$applyAsync();
    };

    /*
     * Reload attachments.
     */
    c.refreshAttachments = function() {

        c.server.get({
            action: "get_attachments",
            sys_id: c.data.sys_id
        }).then(function(response) {

            c.attachments =
                response.data.attachments || [];
        });
    };

    /*
     * Delete attachment.
     */
    c.deleteAttachment = function(
        attachment
    ) {

        if (
            !attachment ||
            !attachment.sys_id
        ) {
            return;
        }

        if (
            !$window.confirm(
                "Do you want to delete this attachment?"
            )
        ) {
            return;
        }

        c.server.get({
            action: "delete_attachment",
            sys_id: c.data.sys_id,
            attachment_sys_id:
                attachment.sys_id
        }).then(function(response) {

            if (response.data.success) {

                spUtil.addInfoMessage(
                    response.data.message
                );

                c.refreshAttachments();
                return;
            }

            spUtil.addErrorMessage(
                response.data.message ||
                "Unable to delete the attachment."
            );
        });
    };

    /*
     * Check whether payment is required.
     */
    c.paymentRequired = function() {

        return (
            c.data.isPaymentRequired || ""
        ).toString().toLowerCase() === "yes";
    };

    /*
     * Clear payment details when No is selected.
     */
    c.paymentChanged = function() {

        if (!c.paymentRequired()) {

            c.data.currency = "";
            c.data.courseFee = null;
            c.data.otherExpenses = null;
            c.data.specifyOtherExpenses = "";
            c.data.totalCost = null;
        }
    };

    /*
     * Calculate total cost.
     */
    c.calculateTotalCost = function() {

        var courseFee =
            parseFloat(
                c.data.courseFee
            ) || 0;

        var otherExpenses =
            parseFloat(
                c.data.otherExpenses
            ) || 0;

        c.data.totalCost =
            parseFloat(
                (
                    courseFee +
                    otherExpenses
                ).toFixed(2)
            );
    };

    /*
     * Clear L2 manager when L2 is not required.
     */
    c.l2RequirementChanged = function() {

        if (
            c.data.l2Required === "no"
        ) {
            c.l2ManagerField = {
                displayValue: "",
                value: "",
                name: "u_management_l2"
            };
        }
    };

    /*
     * Format Date as yyyy-MM-dd for server.
     */
    c.formatDate = function(value) {

        if (!value) {
            return "";
        }

        if (!angular.isDate(value)) {
            return value
                .toString()
                .substring(0, 10);
        }

        var year =
            value.getFullYear();

        var month =
            value.getMonth() + 1;

        var day =
            value.getDate();

        month =
            month < 10
                ? "0" + month
                : month;

        day =
            day < 10
                ? "0" + day
                : day;

        return (
            year +
            "-" +
            month +
            "-" +
            day
        );
    };

    /*
     * Update and submit the learning application.
     */
    c.update = function(form) {

        if (c.submitting) {
            return;
        }

        if (!c.data.canSubmit) {

            spUtil.addErrorMessage(
                "This learning application cannot be submitted from its current status."
            );

            return;
        }

        if (form) {
            form.$setSubmitted();
        }

        /*
         * Employee Name validation.
         */
        if (
            !c.employeeField ||
            !c.employeeField.value
        ) {
            spUtil.addErrorMessage(
                "Please select Employee Name."
            );
            return;
        }

        /*
         * Employee Email validation.
         */
        if (
            !c.data.employeeEmail ||
            !c.data.employeeEmail
                .toString()
                .trim()
        ) {
            spUtil.addErrorMessage(
                "Please enter Employee Email."
            );
            return;
        }

        /*
         * Country validation.
         */
        if (
            !c.countryField ||
            !c.countryField.value
        ) {
            spUtil.addErrorMessage(
                "Please select Country."
            );
            return;
        }

        /*
         * Manager validation.
         */
        if (
            !c.managerField ||
            !c.managerField.value
        ) {
            spUtil.addErrorMessage(
                "Please select In Company Manager."
            );
            return;
        }

        /*
         * L2 Manager validation.
         */
        if (
            c.data.l2Required === "yes" &&
            (
                !c.l2ManagerField ||
                !c.l2ManagerField.value
            )
        ) {
            spUtil.addErrorMessage(
                "Please select Management L2."
            );
            return;
        }

        /*
         * Course Title validation.
         */
        if (
            !c.data.courseTitle ||
            !c.data.courseTitle
                .toString()
                .trim()
        ) {
            spUtil.addErrorMessage(
                "Please enter Course Title."
            );
            return;
        }

        /*
         * Course Type validation.
         */
        if (!c.data.courseType) {
            spUtil.addErrorMessage(
                "Please select Course Type."
            );
            return;
        }

        /*
         * Course Format validation.
         */
        if (!c.data.courseFormat) {
            spUtil.addErrorMessage(
                "Please select Course Format."
            );
            return;
        }

        /*
         * Training Country validation.
         */
        if (
            !c.trainingCountryField ||
            !c.trainingCountryField.value
        ) {
            spUtil.addErrorMessage(
                "Please select Training Location Country."
            );
            return;
        }

        /*
         * Course Start Date validation.
         */
        if (!c.data.courseStartDate) {
            spUtil.addErrorMessage(
                "Please select Course Start Date."
            );
            return;
        }

        /*
         * Course End Date validation.
         */
        if (!c.data.courseEndDate) {
            spUtil.addErrorMessage(
                "Please select Course End Date."
            );
            return;
        }

        /*
         * Date order validation.
         */
        var startDate =
            new Date(
                c.data.courseStartDate
            );

        var endDate =
            new Date(
                c.data.courseEndDate
            );

        startDate.setHours(
            0,
            0,
            0,
            0
        );

        endDate.setHours(
            0,
            0,
            0,
            0
        );

        if (endDate < startDate) {

            spUtil.addErrorMessage(
                "Course End Date must be after or equal to Course Start Date."
            );

            return;
        }

        /*
         * Currency validation.
         */
        if (
            c.paymentRequired() &&
            !c.data.currency
        ) {
            spUtil.addErrorMessage(
                "Please select Currency."
            );
            return;
        }

        /*
         * Prevent duplicate submission.
         */
        c.submitting = true;

        c.server.get({

            action: "update_and_submit",
            sys_id: c.data.sys_id,

            employee:
                c.employeeField.value,

            employeeEmail:
                c.data.employeeEmail
                    .toString()
                    .trim(),

            country:
                c.countryField.value,

            manager:
                c.managerField.value,

            l2Manager:
                c.l2ManagerField &&
                c.l2ManagerField.value
                    ? c.l2ManagerField.value
                    : "",

            l2Required:
                c.data.l2Required || "no",

            courseTitle:
                c.data.courseTitle,

            courseType:
                c.data.courseType,

            courseFormat:
                c.data.courseFormat,

            trainingCountry:
                c.trainingCountryField.value,

            trainingProviderName:
                c.data.trainingProviderName || "",

            courseStartDate:
                c.formatDate(
                    c.data.courseStartDate
                ),

            courseEndDate:
                c.formatDate(
                    c.data.courseEndDate
                ),

            totalTrainingHours:
                c.data.totalTrainingHours || "",

            isPaymentRequired:
                c.data.isPaymentRequired || "no",

            currency:
                c.data.currency || "",

            courseFee:
                c.data.courseFee || "",

            otherExpenses:
                c.data.otherExpenses || "",

            specifyOtherExpenses:
                c.data.specifyOtherExpenses || "",

            totalCost:
                c.data.totalCost || "",

            acknowledgement:
                c.data.acknowledgement === true,

            comment:
                c.data.comment || ""

        }).then(
            function(response) {

                c.submitting = false;

                if (
                    response.data.success
                ) {

                    spUtil.addInfoMessage(
                        response.data.message ||
                        "Learning application submitted successfully."
                    );

                    $timeout(
                        function() {
                            $window.location.href =
                                "/esc?id=check_my_records_asean";
                        },
                        800
                    );

                    return;
                }

                spUtil.addErrorMessage(
                    response.data.message ||
                    "Unable to submit the learning application."
                );
            },
            function() {

                c.submitting = false;

                spUtil.addErrorMessage(
                    "An unexpected error occurred while submitting."
                );
            }
        );
    };

    /*
     * Restore original values.
     */
    c.clearForm = function() {

        c.data =
            angular.copy(originalData);

        c.employeeField =
            angular.copy(originalEmployee);

        c.countryField =
            angular.copy(originalCountry);

        c.managerField =
            angular.copy(originalManager);

        c.l2ManagerField =
            angular.copy(originalL2Manager);

        c.trainingCountryField =
            angular.copy(
                originalTrainingCountry
            );

        spUtil.addInfoMessage(
            "Changes have been cleared."
        );
    };

    /*
     * Return to My Records page.
     */
    c.cancel = function() {

        $window.location.href =
            "/esc?id=check_my_records_asean";
    };
};

sp_widget.css:
.learning-page {
  min-height: 100vh;
  padding: 38px 25px;
  background: #f3f7f9;
  font-family: Arial, Helvetica, sans-serif;
  color: #1f2937;
}

.learning-card {
  max-width: 1470px;
  margin: 0 auto;
  overflow: hidden;
  background: #ffffff;
  border: 1px solid #d7dee5;
  border-radius: 11px;
  box-shadow: 0 6px 18px rgba(28, 45, 64, 0.12);
}

.learning-header {
  padding: 34px 40px 32px;
  border-bottom: 1px solid #e2e6ea;
}

.header-title {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-bottom: 18px;
  color: #f47b20;
  font-size: 29px;
  font-weight: 500;
}

.header-title i {
  font-size: 32px;
}

.application-number {
  color: #3e4650;
  font-size: 18px;
}

.learning-body {
  padding: 38px 42px 42px;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: 22px;
  row-gap: 25px;
}

.field-block {
  min-width: 0;
}

.field-block.full-width {
  width: 100%;
}

.field-block label {
  display: block;
  margin-bottom: 10px;
  color: #272d35;
  font-size: 16px;
  font-weight: 600;
}

.required-label::before {
  content: "* ";
  color: #d9534f;
}

.form-control {
  width: 100%;
  height: 57px;
  padding: 12px 16px;
  border: 1px solid #cbd5df;
  border-radius: 5px;
  background: #ffffff;
  color: #111827;
  font-size: 16px;
  box-shadow: none;
}

.form-control:focus {
  border-color: #f47b20;
  outline: none;
  box-shadow: 0 0 0 2px rgba(244, 123, 32, 0.12);
}

.readonly-field {
  background: #f7f9fb;
  cursor: not-allowed;
}

.textarea-control {
  height: auto;
  min-height: 95px;
  resize: vertical;
}

.section-title {
  margin: 34px 0 18px;
  color: #252b32;
  font-size: 20px;
  font-weight: 600;
}

.acknowledgement-block {
  padding: 4px 0 8px;
  font-size: 15px;
}

.acknowledgement-block label {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  font-weight: 400;
  line-height: 1.5;
}

.acknowledgement-block input {
  margin-top: 3px;
}

/* Record picker */

sn-record-picker .select2-container {
  width: 100% !important;
}

sn-record-picker .select2-choice {
  height: 57px !important;
  padding: 12px 42px 12px 16px !important;
  border: 1px solid #cbd5df !important;
  border-radius: 5px !important;
  background: #ffffff !important;
  box-shadow: none !important;
}

sn-record-picker .select2-choice:hover {
  border-color: #aebbc7 !important;
}

sn-record-picker .select2-container-active .select2-choice {
  border-color: #f47b20 !important;
  box-shadow: 0 0 0 2px rgba(244, 123, 32, 0.12) !important;
}

sn-record-picker .select2-chosen {
  line-height: 31px !important;
  font-size: 16px !important;
}

sn-record-picker .select2-arrow {
  width: 38px !important;
  border-left: 1px solid #cbd5df !important;
  background: #ffffff !important;
}

sn-record-picker .select2-arrow b {
  background-position: 0 15px !important;
}

/* Attachment section */

.attachment-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.attachment-icon-button {
  padding: 9px 15px;
  border: 1px solid #f47b20;
  border-radius: 5px;
  background: #ffffff;
  color: #f47b20;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

.attachment-icon-button:hover {
  background: #fff5ed;
}

.attachment-icon-button:focus {
  outline: none;
  box-shadow: 0 0 0 2px rgba(244, 123, 32, 0.15);
}

.attachment-icon-button i {
  margin-right: 7px;
}

.hidden-file-input {
  display: none;
}

.attachment-empty {
  padding: 18px;
  border: 1px dashed #ccd5de;
  border-radius: 5px;
  background: #fafbfc;
  color: #6b7280;
  text-align: center;
}

.attachment-list {
  overflow: hidden;
  border: 1px solid #dce2e8;
  border-radius: 6px;
}

.attachment-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  border-bottom: 1px solid #e6eaee;
  background: #ffffff;
}

.attachment-row:last-child {
  border-bottom: 0;
}

.attachment-row:hover {
  background: #fafbfc;
}

.attachment-information {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.attachment-information a {
  overflow: hidden;
  color: #0875b5;
  font-size: 15px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.attachment-information a:hover {
  color: #055e91;
  text-decoration: underline;
}

.attachment-file-icon {
  flex-shrink: 0;
  color: #f47b20;
  font-size: 19px;
}

.attachment-size {
  flex-shrink: 0;
  color: #7b8490;
  font-size: 13px;
}

.delete-attachment-button {
  flex-shrink: 0;
  padding: 5px 8px;
  border: 0;
  background: transparent;
  color: #d9534f;
  font-size: 16px;
  cursor: pointer;
}

.delete-attachment-button:hover {
  color: #b52b27;
}

.delete-attachment-button:focus {
  outline: none;
}

/* Action buttons */

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 15px;
  margin-top: 38px;
  padding-top: 25px;
  border-top: 1px solid #e2e6ea;
}

.btn-action {
  min-width: 120px;
  padding: 12px 22px;
  border-radius: 5px;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
}

.btn-cancel {
  border: 1px solid #cbd5df;
  background: #ffffff;
  color: #4b5563;
}

.btn-cancel:hover {
  background: #f7f9fb;
}

.btn-clear {
  border: 1px solid #f47b20;
  background: #ffffff;
  color: #f47b20;
}

.btn-clear:hover {
  background: #fff5ed;
}

.btn-update {
  border: 1px solid #f47b20;
  background: #f47b20;
  color: #ffffff;
}

.btn-update:hover {
  border-color: #dc6814;
  background: #dc6814;
}

.btn-action:focus {
  outline: none;
  box-shadow: 0 0 0 2px rgba(244, 123, 32, 0.16);
}

.btn-action[disabled] {
  cursor: not-allowed;
  opacity: 0.6;
}

/* Unsupported status message */

.submit-status-message {
  margin-top: 18px;
  margin-bottom: 0;
  border: 1px solid #f0d58c;
  background: #fff8df;
  color: #725b18;
}

/* Record not found */

.record-error-container {
  max-width: 1200px;
  margin: 30px auto;
  padding: 0 20px;
}

/* Tablet */

@media screen and (max-width: 991px) {
  .learning-header {
    padding: 28px 30px;
  }

  .learning-body {
    padding: 30px;
  }

  .form-grid {
    column-gap: 18px;
    row-gap: 22px;
  }
}

/* Mobile */

@media screen and (max-width: 767px) {
  .learning-page {
    padding: 15px;
  }

  .learning-header,
  .learning-body {
    padding: 24px 18px;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

  .header-title {
    align-items: flex-start;
    font-size: 23px;
  }

  .header-title i {
    font-size: 26px;
  }

  .application-number {
    font-size: 16px;
  }

  .attachment-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
  }

  .attachment-icon-button {
    width: 100%;
  }

  .attachment-row {
    align-items: flex-start;
    gap: 12px;
  }

  .attachment-information {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .attachment-information a {
    max-width: 210px;
  }

  .attachment-size {
    width: 100%;
    padding-left: 29px;
  }

  .form-actions {
    flex-direction: column-reverse;
  }

  .btn-action {
    width: 100%;
  }
}

sp_widget.script:
(function() {

    var TABLE_NAME =
        "x_1549902_asean_0_learning_application";

    data.table = TABLE_NAME;
    data.notFound = false;
    data.success = false;
    data.message = "";
    data.debugMessage = "";
    data.attachments = [];

    var sysId = "";

    if (input && input.sys_id) {
        sysId = input.sys_id.toString();
    } else {
        sysId = (
            $sp.getParameter("sys_id") || ""
        ).toString();
    }

    function getValue(record, fieldName) {
        if (
            !record ||
            !record.isValidField(fieldName)
        ) {
            return "";
        }

        return record.getValue(fieldName) || "";
    }

    function getDisplayValue(record, fieldName) {
        if (
            !record ||
            !record.isValidField(fieldName)
        ) {
            return "";
        }

        return record.getDisplayValue(fieldName) || "";
    }

    function setValue(record, fieldName, value) {
        if (
            !record ||
            !record.isValidField(fieldName)
        ) {
            return;
        }

        record.setValue(
            fieldName,
            value === null ||
            value === undefined
                ? ""
                : value
        );
    }

    function getChoiceOptions(
        tableName,
        fieldName
    ) {
        var options = [];

        var choiceGR =
            new GlideRecord("sys_choice");

        choiceGR.addQuery("name", tableName);
        choiceGR.addQuery("element", fieldName);
        choiceGR.addQuery("inactive", false);
        choiceGR.orderBy("sequence");
        choiceGR.orderBy("label");
        choiceGR.query();

        while (choiceGR.next()) {
            options.push({
                label: choiceGR.getValue("label"),
                value: choiceGR.getValue("value")
            });
        }

        return options;
    }

    function getCurrencyOptions() {
        return [
            {
                label: "EUR",
                value: "EUR"
            },
            {
                label: "INR",
                value: "INR"
            },
            {
                label: "USD",
                value: "USD"
            },
            {
                label: "GBP",
                value: "GBP"
            },
            {
                label: "SGD",
                value: "SGD"
            },
            {
                label: "MYR",
                value: "MYR"
            },
            {
                label: "THB",
                value: "THB"
            },
            {
                label: "IDR",
                value: "IDR"
            },
            {
                label: "PHP",
                value: "PHP"
            },
            {
                label: "VND",
                value: "VND"
            }
        ];
    }

    function formatFileSize(sizeBytes) {
        var size = parseInt(sizeBytes, 10) || 0;

        if (size < 1024) {
            return size + " B";
        }

        if (size < 1024 * 1024) {
            return (
                size / 1024
            ).toFixed(1) + " KB";
        }

        return (
            size / (1024 * 1024)
        ).toFixed(1) + " MB";
    }

    function getAttachments(recordSysId) {
        var attachments = [];

        var attachmentGR =
            new GlideRecord("sys_attachment");

        attachmentGR.addQuery(
            "table_name",
            TABLE_NAME
        );

        attachmentGR.addQuery(
            "table_sys_id",
            recordSysId
        );

        attachmentGR.orderByDesc("sys_created_on");
        attachmentGR.query();

        while (attachmentGR.next()) {

            var attachmentSysId =
                attachmentGR.getUniqueValue();

            attachments.push({
                sys_id: attachmentSysId,

                file_name:
                    attachmentGR.getValue(
                        "file_name"
                    ),

                content_type:
                    attachmentGR.getValue(
                        "content_type"
                    ),

                size_bytes:
                    attachmentGR.getValue(
                        "size_bytes"
                    ),

                sizeDisplay:
                    formatFileSize(
                        attachmentGR.getValue(
                            "size_bytes"
                        )
                    ),

                downloadUrl:
                    "/sys_attachment.do?sys_id=" +
                    attachmentSysId
            });
        }

        return attachments;
    }

    /*
     * Get attachments after upload.
     */
    if (
        input &&
        input.action === "get_attachments"
    ) {
        data.attachments =
            getAttachments(sysId);

        return;
    }

    /*
     * Delete attachment.
     */
    if (
        input &&
        input.action === "delete_attachment"
    ) {
        if (!input.attachment_sys_id) {
            data.success = false;
            data.message =
                "Attachment ID is missing.";
            return;
        }

        var attachment =
            new GlideRecord("sys_attachment");

        if (
            !attachment.get(
                input.attachment_sys_id
            )
        ) {
            data.success = false;
            data.message =
                "Attachment could not be found.";
            return;
        }

        if (
            attachment.getValue("table_name") !==
                TABLE_NAME ||
            attachment.getValue("table_sys_id") !==
                sysId
        ) {
            data.success = false;
            data.message =
                "The attachment does not belong to this application.";
            return;
        }

        attachment.deleteRecord();

        data.success = true;
        data.message =
            "Attachment deleted successfully.";

        return;
    }

    /*
     * Initial load.
     */
    if (!input) {

        data.loggedInUserEmail =
            gs.getUser().getEmail() || "";

        data.userLevel = "Employee";

        data.courseTypeOptions =
            getChoiceOptions(
                TABLE_NAME,
                "u_course_type"
            );

        data.courseFormatOptions =
            getChoiceOptions(
                TABLE_NAME,
                "u_course_format"
            );

        data.currencyOptions =
            getCurrencyOptions();

        if (!sysId) {
            data.notFound = true;
            data.debugMessage =
                "The sys_id URL parameter is missing.";
            return;
        }

        var gr = new GlideRecord(TABLE_NAME);

        if (!gr.get(sysId)) {
            data.notFound = true;
            data.debugMessage =
                "No record was found for sys_id: " +
                sysId;
            return;
        }

        data.sys_id = gr.getUniqueValue();

        data.learningId =
            getDisplayValue(gr, "number");

        data.status =
            getDisplayValue(gr, "u_status");

        data.statusValue =
            getValue(gr, "u_status");

        /*
         * These are the statuses where the
         * Submit button is available.
         */
        data.canSubmit = [
            "draft",
            "return_by_manager",
            "return_by_l2",
            "return_by_hr"
        ].indexOf(data.statusValue) > -1;

        data.employee =
            getValue(
                gr,
                "u_employee_name"
            );

        data.employeeDisplay =
            getDisplayValue(
                gr,
                "u_employee_name"
            );

        data.employeeEmail =
            getValue(
                gr,
                "u_employee_email"
            );

        data.country =
            getValue(gr, "u_country");

        data.countryDisplay =
            getDisplayValue(
                gr,
                "u_country"
            );

        data.manager =
            getValue(
                gr,
                "u_manager_email"
            );

        data.managerDisplay =
            getDisplayValue(
                gr,
                "u_manager_email"
            );

        data.l2Manager =
            getValue(
                gr,
                "u_management_l2"
            );

        data.l2ManagerDisplay =
            getDisplayValue(
                gr,
                "u_management_l2"
            );

        data.l2Required =
            getValue(
                gr,
                "manager_approval_l2_required"
            );

        data.courseTitle =
            getValue(
                gr,
                "u_course_title"
            );

        data.courseType =
            getValue(
                gr,
                "u_course_type"
            );

        data.courseFormat =
            getValue(
                gr,
                "u_course_format"
            );

        data.trainingCountry =
            getValue(
                gr,
                "u_training_country"
            );

        data.trainingCountryDisplay =
            getDisplayValue(
                gr,
                "u_training_country"
            );

        /*
         * If the training country is a string
         * containing a core_country sys_id,
         * resolve its display name.
         */
        if (
            data.trainingCountry &&
            data.trainingCountryDisplay ===
                data.trainingCountry
        ) {
            var countryGR =
                new GlideRecord("core_country");

            if (
                countryGR.get(
                    data.trainingCountry
                )
            ) {
                data.trainingCountryDisplay =
                    countryGR.getDisplayValue(
                        "name"
                    );
            }
        }

        data.trainingProviderName =
            getValue(
                gr,
                "u_training_provider_name"
            );

        data.courseStartDate =
            getValue(
                gr,
                "course_start_date"
            );

        data.courseEndDate =
            getValue(
                gr,
                "u_course_end_date"
            );

        data.totalTrainingHours =
            parseFloat(
                getValue(
                    gr,
                    "u_total_training_hours"
                ) || 0
            );

        data.isPaymentRequired =
            getValue(
                gr,
                "is_payment_required"
            );

        data.currency =
            getValue(gr, "currency");

        data.courseFee =
            parseFloat(
                getValue(
                    gr,
                    "u_course_fee"
                ) || 0
            );

        data.otherExpenses =
            parseFloat(
                getValue(
                    gr,
                    "u_other_expenses"
                ) || 0
            );

        data.specifyOtherExpenses =
            getValue(
                gr,
                "u_specify_other_expenses"
            );

        data.totalCost =
            parseFloat(
                getValue(
                    gr,
                    "u_total_cost"
                ) || 0
            );

        data.acknowledgement =
            getValue(
                gr,
                "acknowlegment"
            ) === "true";

        data.comment =
            getValue(
                gr,
                "u_comment"
            );

        data.attachments =
            getAttachments(
                gr.getUniqueValue()
            );

        return;
    }

    /*
     * Update and submit.
     */
    if (
        input &&
        input.action === "update_and_submit"
    ) {

        if (!sysId) {
            data.success = false;
            data.message =
                "Learning Application ID is missing.";
            return;
        }

        var reg =
            new GlideRecord(TABLE_NAME);

        if (!reg.get(sysId)) {
            data.success = false;
            data.message =
                "Learning application could not be found.";
            return;
        }

        /*
         * Always get the current status directly
         * from the database.
         */
        var currentStatus =
            getValue(reg, "u_status");

        var currentStatusDisplay =
            getDisplayValue(
                reg,
                "u_status"
            );

        var nextStatus = "";
        var successMessage = "";

        /*
         * State transition mapping.
         */
        switch (currentStatus) {

            case "draft":

                nextStatus = "submitted";

                successMessage =
                    "Learning application submitted successfully.";

                break;

            case "return_by_manager":

                nextStatus =
                    "pending_manager_approval";

                successMessage =
                    "Learning application submitted for Manager approval.";

                break;

            case "return_by_l2":

                nextStatus =
                    "pending_l2_approval";

                successMessage =
                    "Learning application submitted for L2 approval.";

                break;

            case "return_by_hr":

                nextStatus =
                    "pending_hr_review";

                successMessage =
                    "Learning application submitted for HR review.";

                break;

            default:

                data.success = false;

                data.message =
                    "This learning application cannot be submitted from its current status: " +
                    (
                        currentStatusDisplay ||
                        currentStatus
                    ) +
                    ".";

                return;
        }

        /*
         * Mandatory field validation.
         */
        if (
            !input.employee ||
            !input.employeeEmail ||
            !input.country ||
            !input.manager ||
            !input.courseTitle ||
            !input.courseType ||
            !input.courseFormat ||
            !input.trainingCountry ||
            !input.courseStartDate ||
            !input.courseEndDate
        ) {
            data.success = false;
            data.message =
                "Please complete all mandatory fields.";
            return;
        }

        if (
            input.l2Required === "yes" &&
            !input.l2Manager
        ) {
            data.success = false;
            data.message =
                "Please select Management L2.";
            return;
        }

        /*
         * Date validation.
         */
        var startDate = new GlideDate();

        startDate.setValue(
            input.courseStartDate
        );

        var endDate = new GlideDate();

        endDate.setValue(
            input.courseEndDate
        );

        if (
            endDate.getNumericValue() <
            startDate.getNumericValue()
        ) {
            data.success = false;

            data.message =
                "Course End Date must be after or equal to Course Start Date.";

            return;
        }

        /*
         * Employee information.
         */
        setValue(
            reg,
            "u_employee_name",
            input.employee
        );

        setValue(
            reg,
            "u_employee_email",
            input.employeeEmail
        );

        setValue(
            reg,
            "u_country",
            input.country
        );

        setValue(
            reg,
            "u_manager_email",
            input.manager
        );

        setValue(
            reg,
            "u_management_l2",
            input.l2Manager || ""
        );

        setValue(
            reg,
            "manager_approval_l2_required",
            input.l2Required || "no"
        );

        /*
         * Course information.
         */
        setValue(
            reg,
            "u_course_title",
            input.courseTitle
        );

        setValue(
            reg,
            "short_description",
            input.courseTitle
        );

        setValue(
            reg,
            "u_course_type",
            input.courseType
        );

        setValue(
            reg,
            "u_course_format",
            input.courseFormat
        );

        setValue(
            reg,
            "u_training_country",
            input.trainingCountry
        );

        setValue(
            reg,
            "u_training_provider_name",
            input.trainingProviderName || ""
        );

        setValue(
            reg,
            "course_start_date",
            input.courseStartDate
        );

        setValue(
            reg,
            "u_course_end_date",
            input.courseEndDate
        );

        setValue(
            reg,
            "u_total_training_hours",
            input.totalTrainingHours || ""
        );

        /*
         * Payment information.
         */
        setValue(
            reg,
            "is_payment_required",
            input.isPaymentRequired || "no"
        );

        if (
            input.isPaymentRequired === "yes"
        ) {
            setValue(
                reg,
                "currency",
                input.currency || ""
            );

            setValue(
                reg,
                "u_course_fee",
                input.courseFee || ""
            );

            setValue(
                reg,
                "u_other_expenses",
                input.otherExpenses || ""
            );

            setValue(
                reg,
                "u_specify_other_expenses",
                input.specifyOtherExpenses || ""
            );

            setValue(
                reg,
                "u_total_cost",
                input.totalCost || ""
            );

        } else {

            setValue(
                reg,
                "currency",
                ""
            );

            setValue(
                reg,
                "u_course_fee",
                ""
            );

            setValue(
                reg,
                "u_other_expenses",
                ""
            );

            setValue(
                reg,
                "u_specify_other_expenses",
                ""
            );

            setValue(
                reg,
                "u_total_cost",
                ""
            );
        }

        /*
         * Acknowledgement and comment.
         */
        setValue(
            reg,
            "acknowlegment",
            input.acknowledgement === true
        );

        setValue(
            reg,
            "u_comment",
            input.comment || ""
        );

        /*
         * Resolve new status display label.
         */
        var nextStatusDisplay =
            nextStatus;

        var statusChoiceGR =
            new GlideRecord("sys_choice");

        statusChoiceGR.addQuery(
            "name",
            TABLE_NAME
        );

        statusChoiceGR.addQuery(
            "element",
            "u_status"
        );

        statusChoiceGR.addQuery(
            "value",
            nextStatus
        );

        statusChoiceGR.addQuery(
            "inactive",
            false
        );

        statusChoiceGR.setLimit(1);
        statusChoiceGR.query();

        if (statusChoiceGR.next()) {
            nextStatusDisplay =
                statusChoiceGR.getValue(
                    "label"
                ) || nextStatus;
        }

        /*
         * Add submission details to work notes.
         */
        if (
            reg.isValidField("work_notes")
        ) {
            var workNote =
                "Learning application submitted by " +
                gs.getUserDisplayName() +
                ".\nPrevious Status: " +
                (
                    currentStatusDisplay ||
                    currentStatus
                ) +
                "\nNew Status: " +
                nextStatusDisplay;

            if (
                input.comment &&
                input.comment
                    .toString()
                    .trim()
            ) {
                workNote +=
                    "\n\nComments:\n" +
                    input.comment
                        .toString()
                        .trim();
            }

            reg.setValue(
                "work_notes",
                workNote
            );
        }

        /*
         * Apply status transition.
         */
        setValue(
            reg,
            "u_status",
            nextStatus
        );

        /*
         * Keep platform approval consistent.
         */
        if (
            reg.isValidField("approval")
        ) {
            reg.setValue(
                "approval",
                "requested"
            );
        }

        var updatedSysId =
            reg.update();

        if (updatedSysId) {

            data.success = true;
            data.message = successMessage;

            data.previousStatus =
                currentStatus;

            data.newStatus =
                nextStatus;

        } else {

            data.success = false;

            data.message =
                "Unable to submit the learning application.";
        }

        return;
    }

})();
